DROP TABLE IF EXISTS sessions; DROP TABLE IF EXISTS scores; CREATE TABLE sessions (id TEXT PRIMARY KEY, created INTEGER NOT NULL, found TEXT NOT NULL DEFAULT '[]', attempts INTEGER NOT NULL DEFAULT 0, finished INTEGER NOT NULL DEFAULT 0); CREATE TABLE scores (id INTEGER PRIMARY KEY AUTOINCREMENT, sid TEXT NOT NULL UNIQUE, pseudo TEXT NOT NULL UNIQUE COLLATE NOCASE, score INTEGER NOT NULL, seconds INTEGER NOT NULL, created INTEGER NOT NULL); CREATE INDEX scores_rank ON scores (score DESC, seconds ASC);
